// Generated by scripts/traducir-focos.mjs. Spanish source and calculations are shared.
"use client";

import { useState } from "react";
import { fuenteFocos } from "@/lib/data/focos";
import { aCsv, descargar } from "@/lib/exportar/csv";
import { etiquetaOrigen } from "@/presentation-en/lib/focos/origen";
import { TEXTOS, type Modo } from "@/presentation-en/lib/focos/modo";
import type { Resumen } from "@/lib/focos/tipos";
import estilos from "@/components/sitio/Descargas.module.css";

const ATRIBUCION = "Data: Government of San Luis";
const ATRIBUCION_TODOS = "Data: Government of San Luis and NASA FIRMS";
const ATRIBUCION_INCENDIOS = "Data: NASA (MCD64A1), Government of San Luis and NASA FIRMS";

function porAnioYFuente(resumen: Resumen, modo: Modo) {
  const { porAnioOrigen, porOrigen, fechaMin, fechaMax } = resumen.todos;
  const nombres = porOrigen.map((o) => o.origen);
  const filas = [
    ["year", ...nombres.map(etiquetaOrigen), "total"],
    ...porAnioOrigen.map((a) => {
      const valores = nombres.map((n) => a.origenes[n] ?? 0);
      return [a.anio, ...valores, valores.reduce((s, v) => s + v, 0)];
    }),
    [],
    [
      `# ${modo === "incendios" ? ATRIBUCION_INCENDIOS : ATRIBUCION_TODOS}. Historical series: historical data through October 2024. NASA FIRMS: missing months and subsequent periods. Downloaded ${resumen.descargado}.`,
    ],
  ];
  const prefijo = modo === "incendios" ? "incendios-confirmados" : "focos";
  descargar(
    `san-luis_${prefijo}-por-anio-y-fuente_${fechaMin.slice(0, 4)}-${fechaMax.slice(0, 4)}.csv`,
    aCsv(filas),
    "text/csv;charset=utf-8",
  );
}

function anual(resumen: Resumen, modo: Modo) {
  const T = TEXTOS[modo];
  const incendios = modo === "incendios";
  const { anual: serie, tendencia: t } = resumen.aqua;
  const filas = [
    ["year", T.columnaAnual, "missing_months", "sen_trend", "least_squares_trend"],
    ...serie.map((d) => [
      d.anio,
      incendios ? Math.round(d.total) : d.total,
      d.mesesSinDato,
      Math.round((t.ordenadaSen + t.senAnual * d.anio) * 10) / 10,
      Math.round((t.ordenada + t.pendienteAnual * d.anio) * 10) / 10,
    ]),
    [],
    ["# Mann-Kendall p", Math.round(t.p * 10000) / 10000],
    [`# Sen’s slope (${T.porDecada})`, Math.round(t.senAnual * 100) / 10],
    ["# Significant (p < 0.05)", t.significativa ? "yes" : "no"],
    [
      incendios
        ? `# ${ATRIBUCION_INCENDIOS}. Annual burned area from MCD64A1. Downloaded ${resumen.descargado}.`
        : `# ${ATRIBUCION}. Aqua (MODIS): historical series, supplemented with NASA FIRMS for missing months. Downloaded ${resumen.descargado}.`,
    ],
  ];
  descargar(`san-luis_${T.nombreAnual}_${t.desde}-${t.hasta}.csv`, aCsv(filas), "text/csv;charset=utf-8");
}

async function mensual(resumen: Resumen, modo: Modo) {
  const T = TEXTOS[modo];
  const incendios = modo === "incendios";
  const serie = incendios ? await fuenteFocos.getSerieIncendios() : await fuenteFocos.getSerieMensual();
  const nombres = serie.departamentos.map((d) => d.nombre);
  const filas = [
    ["month", ...nombres, "province_total", "source"],
    ...serie.meses.map((m, i) => {
      const valores = serie.departamentos.map((d) => d.conteos[i]);
      const total = valores.some((v) => v === null) ? null : valores.reduce<number>((s, v) => s + (v ?? 0), 0);
      const fuente = incendios ? "MCD64A1" : etiquetaOrigen(serie.fuentePorMes?.[i] ?? "CONAE");
      return [m, ...valores, total, fuente];
    }),
    [],
    [
      incendios
        ? "# Empty cells: no MCD64A1 granule for the month (not zero). Values are in hectares."
        : "# Empty cells: no source data for the month (not zero).",
    ],
    [
      `# ${incendios ? ATRIBUCION_INCENDIOS : ATRIBUCION}${incendios ? "" : ". Aqua (MODIS): historical series, supplemented with NASA FIRMS for missing months"}. Downloaded ${resumen.descargado}.`,
    ],
  ];
  descargar(
    `san-luis_${T.nombreMensual}_${serie.meses[0]}_${serie.meses.at(-1)}.csv`,
    aCsv(filas),
    "text/csv;charset=utf-8",
  );
}

async function escenarioFuturo(modo: Modo) {
  const ruta = modo === "incendios" ? "/demo/escenario-incendios-en.html" : "/demo/escenario-futuro-en.html";
  const marco = document.querySelector<HTMLIFrameElement>(`iframe[src="${ruta}"]`);
  const ventana = marco?.contentWindow as (Window & { exportarEscenario?: () => { csv: string; nombre: string } }) | null;
  const seleccion = ventana?.exportarEscenario?.();
  if (seleccion) {
    descargar(seleccion.nombre, "\ufeff" + seleccion.csv, "text/csv;charset=utf-8");
    return;
  }
  // Sin el explorador futuro abierto se exporta el horizonte completo.
  const respuesta = await fetch(ruta);
  if (!respuesta.ok) throw new Error("Could not load scenario data");
  const documento = new DOMParser().parseFromString(await respuesta.text(), "text/html");
  const contenido = documento.getElementById("scenario")?.textContent;
  if (!contenido) throw new Error("The scenario has no exportable data");
  const datos = JSON.parse(contenido) as { start: number; end: number; names: string[]; events: [number, number, number, number][] };
  const filas = [
    ["period", "department", "longitude", "latitude", "type"],
    ...datos.events.map(([lon, lat, departamento, mes]) => [
      `${datos.start + Math.floor(mes / 12)}-${String(mes % 12 + 1).padStart(2, "0")}`,
      datos.names[departamento], lon, lat, "SIMULATED",
    ]),
  ];
  descargar(`escenario-${modo}-simulado-${datos.start}-${datos.end}.csv`, aCsv(filas), "text/csv;charset=utf-8");
}

export function Descargas({ resumen, modo = "focos" }: { resumen: Resumen; modo?: Modo }) {
  const [error, setError] = useState<string | null>(null);
  const incendios = modo === "incendios";
  return (
    <section id="descargas" className="seccion seccion-alterna" aria-labelledby="titulo-descargas">
      <div className="contenedor">
        <div className="seccion-cabeza">
          <h2 id="titulo-descargas">Downloads</h2>
          <p> The same figures shown on the site, ready for a spreadsheet or Python. Each file includes its source and identifies months with missing data. </p>
        </div>
        <ul className={estilos.lista}>
          <li>
            <div>
              <h3>{incendios ? "Burned hectares by year" : "Hotspots by year"}</h3>
              <p>
                {incendios
                  ? `Annual burned area, from ${resumen.aqua.tendencia.desde} to ${resumen.aqua.tendencia.hasta}, including the trend line, p-value and Sen’s slope.`
                  : `Annual Aqua series ${resumen.aqua.tendencia.desde} to ${resumen.aqua.tendencia.hasta}, including the trend line, p-value and Sen’s slope.`}
              </p>
            </div>
            <button type="button" className="boton boton-principal" onClick={() => anual(resumen, modo)}> Download CSV </button>
          </li>
          <li>
            <div>
              <h3>{incendios ? "Burned hectares by month and department" : "Hotspots by month and department"}</h3>
              <p> The {resumen.aqua.ranking.length} departments, month by month.{" "}
                {incendios ? "Empty cells indicate months without an MCD64A1 granule." : "Empty cells indicate months with missing data."}
              </p>
            </div>
            <button
              type="button"
              className="boton boton-principal"
              onClick={() => mensual(resumen, modo).catch((e: Error) => setError(e.message))}
            > Download CSV </button>
          </li>
          <li>
            <div>
              <h3>{incendios ? "Fire detections by year and source" : "Hotspots by year and source"}</h3>
              <p>
                {incendios
                  ? "Fire-associated detections by year, from the historical series or NASA FIRMS."
                  : "All site detections by year and source: historical series and NASA FIRMS, including satellites other than Aqua."}
              </p>
            </div>
            <button type="button" className="boton boton-principal" onClick={() => porAnioYFuente(resumen, modo)}> Download CSV </button>
          </li>
            <li>
              <div>
                <h3>{incendios ? "Future scenario based on fire detections" : "Future thermal-hotspot scenario"}</h3>
                <p>Simulated points over ten years. Exports the active scenario filters, or the full horizon from the historical view. These are not observations or confirmed future locations.</p>
              </div>
              <button type="button" className="boton boton-principal" onClick={() => escenarioFuturo(modo).catch((e: Error) => setError(e.message))}> Download CSV </button>
            </li>
        </ul>
        {error && (
          <p role="alert" className={estilos.error}> Could not generate the file: {error}. Please try again in a few seconds. </p>
        )}
      </div>
    </section>
  );
}
